import boto3
from typing import List, Dict, Any
import base64

def extract_table_structure(document_bytes: bytes) -> List[Dict[str, Any]]:
    """
    Extract table cells and row structure from a document using Amazon Textract.

    Args:
        document_bytes: Raw bytes of the document image or PDF.

    Returns:
        List of dictionaries, each representing a table row with cell contents.
    """
    client = boto3.client('textract')

    if document_bytes.startswith(b'%PDF'):
        response = client.analyze_document(
            Document={'Bytes': document_bytes},
            FeatureTypes=['TABLES']
        )
    else:
        response = client.analyze_document(
            Document={'Bytes': document_bytes},
            FeatureTypes=['TABLES']
        )

    tables = []
    blocks = response['Blocks']

    table_blocks = [block for block in blocks if block['BlockType'] == 'TABLE']

    for table in table_blocks:
        rows = {}
        for relationship in table.get('Relationships', []):
            if relationship['Type'] == 'CHILD':
                for cell_id in relationship['Ids']:
                    cell_block = next((b for b in blocks if b['Id'] == cell_id), None)
                    if cell_block and cell_block['BlockType'] == 'CELL':
                        row_index = cell_block.get('RowIndex', 0)
                        col_index = cell_block.get('ColumnIndex', 0)

                        if row_index not in rows:
                            rows[row_index] = {}

                        cell_text = ''
                        for rel in cell_block.get('Relationships', []):
                            if rel['Type'] == 'CHILD':
                                for word_id in rel['Ids']:
                                    word_block = next((b for b in blocks if b['Id'] == word_id), None)
                                    if word_block and word_block['BlockType'] == 'WORD':
                                        cell_text += word_block['Text'] + ' '

                        rows[row_index][col_index] = cell_text.strip()

        sorted_rows = sorted(rows.items())
        for row_idx, cols in sorted_rows:
            sorted_cols = sorted(cols.items())
            row_dict = {
                'row_index': row_idx,
                'cells': [{'column_index': col_idx, 'content': content} 
                         for col_idx, content in sorted_cols]
            }
            tables.append(row_dict)

    return tables
